import{_ as o,o as a,c as e,ag as r}from"./chunks/framework.4s5LDCII.js";const l=JSON.parse('{"title":"AI Agent 三层路线：从文献检索助手到家庭管家的合规路径","description":"","frontmatter":{},"headers":[],"relativePath":"project/adr/0012-ai-agent-roadmap.md","filePath":"project/adr/0012-ai-agent-roadmap.md"}'),n={name:"project/adr/0012-ai-agent-roadmap.md"};function s(i,t,u,g,p,_){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="ai-agent-三层路线-从文献检索助手到家庭管家的合规路径" tabindex="-1">AI Agent 三层路线：从文献检索助手到家庭管家的合规路径 <a class="header-anchor" href="#ai-agent-三层路线-从文献检索助手到家庭管家的合规路径" aria-label="Permalink to &quot;AI Agent 三层路线：从文献检索助手到家庭管家的合规路径&quot;">​</a></h1><p>用户提出远期目标：将本站数据应用于 AI agent，为家庭和个人提供建议。回答是&quot;可以，但必须分层&quot;——因为&quot;给建议&quot;在 2025 年网信办新规和现行红线（ADR 0004）下有完全不同的合规性质。路线定为三层：</p><ul><li><strong>第一层（已规划，随时可做）——文献检索助手</strong>：AI 只做检索与摘录，回答&quot;官方怎么说 X&quot;时返回原文出处与原句，不生成结论、不做个性化。这就是 ADR 0004 的二期方案，语料的 front-matter 结构与页码出处就是为它准备的。</li><li><strong>第二层（中期）——规则化&quot;家庭管家&quot;</strong>：基于用户自主提供的标签（如&quot;家有高血压老人&quot;），推送对应官方指南的<strong>模板化内容</strong>（食谱、核查清单、提醒），所有输出仍然逐条带出处，AI 不做开放式医学生成。定位是&quot;整理与提醒工具&quot;，不是&quot;顾问&quot;。</li><li><strong>第三层（远期，资质前置）——个性化建议</strong>：生成个性化膳食/健康建议属于生产医疗健康科普甚至健康咨询行为，需要医疗资质或与持牌机构合作（白名单三级来源），并遵守生成式 AI 服务管理规定。资质未到位前<strong>不做</strong>。</li></ul><p>任何一层的输出都必须保留&quot;逐条可溯源、以医嘱为准&quot;的边界。本 ADR 取代 ADR 0004 中&quot;二期只做文献检索助手&quot;的单一表述，将其扩展为三层路线的第一层。</p>',4)])])}const q=o(n,[["render",s]]);export{l as __pageData,q as default};
